import { Card, CardHeader, Grid } from '@neoflo/atoms';

<Grid container spacing={3}>
  {metrics.map((metric) => (
    <Grid key={metric.id} size={{ xs: 12, sm: 6, md: 4 }}>
      <Card component="article" sx={{ height: "100%" }}>
        <CardHeader title={metric.value} subheader={metric.label} />
      </Card>
    </Grid>
  ))}
</Grid>

{sections.map((section) => (
  <Box key={section.id}>
    <Button
      appearance="text"
      onClick={() => toggle(section.id)}
      aria-expanded={openIds.includes(section.id)}
      aria-controls={`section-${section.id}`}
    >
      {section.title}
    </Button>
    <Collapse in={openIds.includes(section.id)} timeout="auto" unmountOnExit>
      <Box id={`section-${section.id}`} sx={{ px: 2, pb: 2 }}>
        {section.body}
      </Box>
    </Collapse>
  </Box>
))}

// Filler styling, reused across the examples below. `band` outlines
// the space each Container was given, so its bounds are visible.
const panel = { p: 2, borderRadius: 1, bgcolor: 'action.hover', textAlign: 'center' };
const band = { borderRadius: 1, border: '1px dashed', borderColor: 'text.disabled' };

<Box sx={band}>
  <Container maxWidth="sm">
    <Box sx={panel}>maxWidth=sm — 600px, then centred</Box>
  </Container>
</Box>

import { Divider, Stack, Typography } from '@neoflo/atoms';

<Stack
  direction="row"
  spacing={2}
  divider={<Divider orientation="vertical" flexItem />}
>
  <Typography variant="body2">12 open</Typography>
  <Typography variant="body2">4 closed</Typography>
  <Typography variant="body2">1 blocked</Typography>
</Stack>

const [sort, setSort] = React.useState("name");

<Menu anchorEl={anchorEl} open={Boolean(anchorEl)} onClose={close}>
  {["name", "date", "size"].map((option) => (
    <MenuItem
      key={option}
      selected={option === sort}
      onClick={() => {
        setSort(option);
        close();
      }}
    >
      {option}
    </MenuItem>
  ))}
</Menu>

{loading ? (
  <Skeleton variant="circular">
    <Avatar size="md" />
  </Skeleton>
) : (
  <Avatar size="md" src={user.avatarUrl} name={user.name} />
)}

import InputAdornment from '@mui/material/InputAdornment';
import { MagnifyingGlassIcon } from '@neoflo/atoms/icons';

<TextField
  label="Search"
  placeholder="Search anything"
  startAdornment={
    <InputAdornment position="start">
      <MagnifyingGlassIcon size={16} />
    </InputAdornment>
  }
/>

import { XIcon } from '@neoflo/atoms/icons';

<TextField
  label="Search"
  endAdornment={
    <IconButton appearance="text" size="sm" aria-label="Clear" onClick={handleClear}>
      <XIcon />
    </IconButton>
  }
/>

import InputAdornment from '@mui/material/InputAdornment';
import { EyeIcon, LockIcon } from '@neoflo/atoms/icons';

<TextField
  label="Password"
  placeholder="Enter password"
  startAdornment={
    <InputAdornment position="start">
      <LockIcon size={16} />
    </InputAdornment>
  }
  endAdornment={
    <IconButton appearance="text" size="sm" aria-label="Show password" onClick={handleToggleVisibility}>
      <EyeIcon />
    </IconButton>
  }
/>

const EXIT = 195;

{actions.map((action, index) => (
  <Zoom
    key={action.id}
    in={tab === index}
    timeout={{ enter: 225, exit: EXIT }}
    style={{ transitionDelay: tab === index ? `${EXIT}ms` : "0ms" }}
    unmountOnExit
  >
    <IconButton aria-label={action.label}>{action.icon}</IconButton>
  </Zoom>
))}
